def make_key(store=None, job_text=None, profile_version=None, criteria_version=None, compute=None):
    # All inputs affect caching; changing any input causes recompute
    # Even None for unchanged position triggers fresh computation only if it differs from stored key
    # Use tuple with explicit None representations to avoid ambiguous concatenation keys
    return (store is not None) + ('_' if store else '') + ('__' if store is not None and job_text is not None else 'job_none') + ('_J' if job_text else '') + str(len(job_text or 0))
